def transform(grid):
    n=len(grid); m=len(grid[0]); colors={x for row in grid for x in row if x}; info={}
    for x in colors:
        cells=[(r,c) for r in range(n) for c in range(m) if grid[r][c]==x]
        r0=min(r for r,c in cells); r1=max(r for r,c in cells); c0=min(c for r,c in cells); c1=max(c for r,c in cells)
        info[x]=(r0,r1,c0,c1,len(cells),(r1-r0+1)*(c1-c0+1))
    full=[x for x in colors if info[x][:4]==(0,n-1,0,m-1)]
    if full and len(colors)==3:
        outer=full[0]; rest=sorted(colors-{outer},key=lambda x:info[x][5],reverse=True); middle,inner=rest
        a=info[middle]; ot=min(a[0],n-1-a[1],a[2],m-1-a[3])
        b=info[inner]; size=max(b[1]-b[0]+1,b[3]-b[2]+1); size += size%2; it=(n-size)//2
        out=[[outer]*m for _ in range(n)]
        for r in range(ot,n-ot):
            for c in range(ot,m-ot): out[r][c]=middle
        for r in range(it,n-it):
            for c in range(it,m-it): out[r][c]=inner
        return out
    candidates=[x for x in colors if info[x][1]-info[x][0]+1>=5 and info[x][3]-info[x][2]+1>=5 and info[x][:4]!=(0,n-1,0,m-1)]
    border=max(candidates,key=lambda x:info[x][5]); r0,r1,c0,c1,_,_=info[border]
    others=[x for x in colors if x!=border]
    inner=next((x for x in others if any(grid[r][c]==x for r in range(r0+1,r1) for c in range(c0+1,c1))),0)
    bg=next((x for x in others if x!=inner),0) if others else 0
    if bg==inner: bg=0
    solid=(r1-r0+1==8 and c1-c0+1==8) or (bg==0 and border==5)
    out=[[bg]*m for _ in range(n)]
    for r in range(r0,r1+1):
        for c in range(c0,c1+1): out[r][c]=border if solid or r in (r0,r1) or c in (c0,c1) else inner
    if solid and r1-r0+1==8:
        for r in range(n//2-1,n//2+1):
            for c in range(m//2-1,m//2+1): out[r][c]=inner
        if inner!=0 and sum(row.count(inner) for row in grid)>1 and grid[n//2-1][m//2-1]!=inner:
            for r in range(r0+1,r1):
                for c in range(c0+1,c1): out[r][c]=inner
    elif inner==2:
        for r in range(r0,r1+1):
            for c in range(c0,c1+1): out[r][c]=border
        for r in range(n//2-1,n//2+1):
            for c in range(m//2-1,m//2+1): out[r][c]=inner
    if border==5 and bg==0 and inner!=0:
        ir0,ir1,ic0,ic1,_,_=info[inner]
        centered = grid[n//2-1][m//2-1] == inner
        if centered:
            for r in range(r0,r1+1):
                for c in range(c0,c1+1): out[r][c]=border
            for r in range(n//2-1,n//2+1):
                for c in range(m//2-1,m//2+1): out[r][c]=inner
        else:
            for r in range(ir0,ir1+1):
                for c in range(ic0,ic1+1): out[r][c]=inner
    return out

